UPDATE proj_project_task_assignment
SET effective_to = #{query.effectiveTo},
    version = version + 1,
    updater = #{query.updater},
    update_time = #{query.effectiveTo}
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.assignmentId}
  AND version = #{query.expectedVersion}
  AND current_marker = 1
  AND effective_to IS NULL
  AND effective_from <= #{query.effectiveTo}
  AND deleted = b'0'
